import{au as e,O as a,C as r,aa as o}from"./chunks/framework.HRLmHRHa.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),i={name:"guide/getting-started.md"};function s(n,t,d,l,g,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h1><p>ImagenHub is a generative media API that gives you access to multiple image generation models — DALL-E 3, Flux, Stable Diffusion, and more — through a single, consistent interface.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What you can do”">​</a></h2><ul><li><strong>Generate images</strong> from text prompts using any supported model</li><li><strong>Browse models</strong> and compare pricing across providers</li><li><strong>Create templates</strong> to save and reuse generation presets</li><li><strong>Track usage</strong> with built-in analytics and cost monitoring</li><li><strong>Bring your own keys</strong> to use your own provider accounts</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h2><ol><li><strong>Get an API key</strong> from the <a href="https://imagenhub.ai" target="_blank" rel="noreferrer">ImagenHub dashboard</a></li><li><strong>Choose a model</strong> from the catalog (or browse programmatically via <code>/models</code>)</li><li><strong>Submit a request</strong> to <code>/process</code> with your prompt and model ID</li><li><strong>Poll or stream</strong> the task status until your images are ready</li></ol><p>Every request is routed to an AI provider, processed, and the generated images are returned as signed URLs valid for one hour.</p><h2 id="base-urls" tabindex="-1">Base URLs <a class="header-anchor" href="#base-urls" aria-label="Permalink to “Base URLs”">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>URL</th></tr></thead><tbody><tr><td>Production</td><td><code>https://api.imagenhub.ai/api</code></td></tr><tr><td>Staging</td><td><code>https://staging-api.imagenhub.ai/api</code></td></tr><tr><td>Local</td><td><code>http://localhost/api</code></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="/guide/quickstart">Quickstart</a> — Generate your first image in under 5 minutes</li><li><a href="/guide/authentication">Authentication</a> — API keys, JWT tokens, and OAuth</li><li><a href="/guide/models-and-providers">Models &amp; Providers</a> — Browse the model catalog</li><li><a href="/api/">API Reference</a> — Full endpoint documentation</li></ul>',11)])])}const m=e(i,[["render",s]]);export{u as __pageData,m as default};
